/** autogenerated **/
Ext._define("esocial.manager.Manage", {
    extend: "toolkit.widget.TabPanel",

    batch: function (value, dispatch) {
        dispatch = core.nullValue(dispatch, true);
        if (value !== undefined) {
            this._batch = value;
            if (dispatch) this.observeBatchEvent();
        } else return this._batch;
    },

    observeBatchEvent: function () {
        if (this.batch()) {
            this.getEventDetailGrid().enable();
            this.getEventDetailGrid().setParam("batch", this.batch());
            this.getEventDetailGrid().setFilterProperty("batches__id", this.batch(), 100);
        } else {
            this.getEventDetailGrid().disable();
            this.getEventDetailGrid().getStore().removeAll();
            this.getEventDetailGrid().setFilterProperty("batches__id", 0, 100, false);
        }
    },

    getTabPanel: function (cfg) {
        if (!this._tabPanel) {
            this._tabPanel = Ext._create("Ext.TabPanel", {
                activeTab: 0,
                region: "center",
                border: true,
                height: 450,
                items: [this.getEventTab(cfg), this.getBatchTab(cfg)],
            });
        }

        return this._tabPanel;
    },

    getEventTab: function (cfg) {
        if (!this._eventTab) {
            this._eventTab = Ext._create("Ext.Panel", {
                layout: "fit",
                title: "Eventos",
                tabPosition: "bottom",
                items: [this.getEventGrid(cfg)],
            });
        }

        return this._eventTab;
    },

    getBatchTab: function (cfg) {
        if (!this._batchTab) {
            this._batchTab = Ext._create("Ext.Panel", {
                layout: "border",
                title: "Lotes",
                tabPosition: "left",
                items: [
                    this.getBatchEventGrid(cfg),
                    this.getEventDetailGrid(cfg)
                ],
            });
        }

        return this._batchTab;
    },

    getEventGrid: function (cfg) {
        if (!this._gridEvent) {
            this._gridEvent = Ext._create("esocial.manager.EventGrid", {
                gridAutoLoad: true,
                maintenance: cfg.maintenance,
                archivedHideMenu: true,
                viewConfig: {
                    scope: this,
                    stripeRows: false,
                    getRowClass: function (record) {
                        if (record.get('is_invalid_cache') == true)
                            return 'x-grid3-dashed x-grid3-read-only';
                    }
                },
            });
        }
        return this._gridEvent;
    },

    getEventDetailGrid: function (cfg) {
        if (!this._gridDetailEvent) {
            this._gridDetailEvent = Ext._create("esocial.manager.EventDetailGrid", {
                region: "south",
                height: 300,
                split: true,
                resource: "ESOCIALEvent",
                gridAutoLoad: false,
                archivedShowAllMenu: true
            });
        }

        return this._gridDetailEvent;
    },

    getBatchEventGrid: function (cfg) {
        if (!this._gridBatch) {
            this._gridBatch = Ext._create("esocial.manager.BatchEventGrid", {
                region: "center",
                gridAutoLoad: true,
                maintenance: cfg.maintenance,
            });
            this._gridBatch.getSelectionModel().on({
                scope: this,
                rowselect: function (sm, index, data) {
                    this.batch(data.get("pk"));
                },
                rowdeselect: function () {
                    this.batch(null);
                },
            });

            this._gridBatch.getStore().on({
                scope: this,
                load: function () {
                    var selected = this._gridBatch.getSelectionModel().getSelected();
                    if (selected) this.batch(selected.get("pk"));
                    else this.batch(null);
                },
            });
        }
        return this._gridBatch;
    },

    getStatusPanel: function (cfg) {
        if (!this._statusPanel) {
            this._statusPanel = Ext._create("Ext.Panel", {
                title: "Eventos",
            });
        }

        return this._statusPanel;
    },

    getTbTextItem: function(cfg){
        if (!this._tbProcessTextItem) {
            this._tbProcessTextItem = Ext._create("Ext.Toolbar.TextItem", {
                text: "AMBIENTE LIBERADO",
                style: {"color": "#14950E", "font-weight": "bold" }
            });
        }

        return this._tbProcessTextItem;
    },

    getProcessEsocial: function () {

        Ext.Ajax.request({
            url: core.callAction('ESOCIALBatchEvent', 'active_process'),
            params: {},
            method: 'GET',
            scope: this,
            success: function (xhr) {
                var rst = Ext.decode(xhr.responseText);
                var tbItem = this.getTbTextItem();

                if (rst.success) {
                    if (rst.processing) {
                        tbItem.setText('AMBIENTE EM PROCESSAMENTO - AGUARDE - ' + rst.message);
                        tbItem.getEl().setStyle('color', '#F00');
                    } else {
                        tbItem.setText('AMBIENTE LIBERADO');
                        tbItem.getEl().setStyle('color', '#14950E');
                    }
                }
            },
            failure: function () {
                console.info(this);
            }
        });
    },

    constructor: function (cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(cfg, {
            maintenance: true,
            title: "ESOCIAL - Gestor - Admin",
        });

        var style = { "color": "#14950E", "font-weight": "bold" };
        var value = "AMBIENTE DE PRODUÇÃO DO ESOCIAL";
        if (cfg.environment == 2){
            style = { color: "#15428B", "font-weight": "bold" };
            value = "HOMOLOGAÇÃO ESOCIAL - PRODUÇÃO RESTRITA";
        }

        Ext.apply(cfg, {
            layout: "border",
            items: [this.getTabPanel(cfg)],
            fbar: {
                style: {"font-weight": "bold", "margin": "0", "padding": "0" },
                buttonAlign: "left",
                scope: this,
                items: [{
                    xtype: 'tbtext',
                    style: style,
                    text: value
                },
                    '->',
                    this.getTbTextItem()
                ],

            },
        });

        esocial.manager.Manage.superclass.constructor.call(this, cfg);
        this.observeBatchEvent();
        // Start a simple clock task that updates a div once per second
        this._taskProcessing = {
            scope: this,
            run: this.getProcessEsocial,
            interval: 5000 //1 second
        }
        Ext.TaskMgr.start(this._taskProcessing);
    },
});

